-- PER Converter for 1 Solar Panel and 1 Battery\n-- Simplified logic for energy conversion\n\nlocal function calculateEnergy(solarPanelOutput, batteryCapacity)\n    -- Simulating total energy generated by solar panel\n    local totalEnergy = solarPanelOutput * 5  -- Assume 5 hours of sunlight\n\n    if totalEnergy > batteryCapacity then\n        return batteryCapacity  -- Energy stored is limited by battery capacity\n    else\n        return totalEnergy  -- All generated energy is stored\n    end\nend\n\nlocal solarPanelOutput = 100  -- Output in watts\nlocal batteryCapacity = 500  -- Capacity in watt-hours\n\nlocal storedEnergy = calculateEnergy(solarPanelOutput, batteryCapacity)\nprint(string.format("Stored Energy: %d Wh", storedEnergy))